import{_ as s,b as a,c as i,g as o}from"./chunks/framework.86O3EbG5.js";const _=JSON.parse('{"title":"做复杂决策","description":"","frontmatter":{"title":"做复杂决策","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/17.md","filePath":"articles/ai/books/ai-modern-approach/17.md"}'),r={name:"articles/ai/books/ai-modern-approach/17.md"};function l(n,t,d,e,p,P){return a(),i("div",null,[...t[0]||(t[0]=[o('<p>第 17 章在第 16 章单步决策的基础上，扩展到序列决策，考虑当前动作影响未来状态与收益。核心内容包括：</p><h2 id="马尔可夫决策过程-mdp" tabindex="-1">马尔可夫决策过程（MDP）</h2><p>五元组：状态集合 S、动作集合 A(s)、转移模型 P(s&#39;|s,a)、奖励函数 R(s,a,s&#39;)（或 R(s,a)）、折扣因子 γ ∈ [0,1]。</p><ul><li><strong>策略 π(s)</strong>：状态到动作的映射</li><li><strong>价值函数</strong>：状态价值 V^π(s) 和动作价值 Q^π(s,a)</li><li><strong>贝尔曼方程</strong>：V^π(s) = Σₛ&#39; P(s&#39;|s,π(s)) [R(s,π(s),s&#39;) + γV^π(s&#39;)]</li><li><strong>最优价值函数 V*</strong> 满足贝尔曼最优方程：V*(s) = max_a Σ P(s&#39;|s,a) [R(s,a,s&#39;) + γV*(s&#39;)]</li></ul><h2 id="求解-mdp-的算法" tabindex="-1">求解 MDP 的算法</h2><ul><li><strong>值迭代</strong>：反复应用贝尔曼最优算子更新 V，直到收敛</li><li><strong>策略迭代</strong>：交替进行策略评估和策略改进，通常收敛更快</li><li><strong>线性规划</strong>：将 MDP 转化为线性规划求解（适用于小规模）</li></ul><h2 id="部分可观测-mdp-pomdp" tabindex="-1">部分可观测 MDP（POMDP）</h2><ul><li>在 MDP 基础上加入观测模型 P(o|s,a)</li><li><strong>信念状态 b(s)</strong> 是状态上的概率分布</li><li><strong>信念状态的更新</strong>：给定动作 a 和观测 o，新信念 b&#39;(s&#39;) = α P(o|s&#39;,a) Σₛ P(s&#39;|s,a) b(s)</li><li><strong>POMDP 的求解</strong>：将问题转化为连续状态 MDP（信念空间），常用方法包括离线值迭代（如 PBVI）和在线规划（如蒙特卡洛树搜索）</li></ul><h2 id="pomdp-的近似方法" tabindex="-1">POMDP 的近似方法</h2><ul><li>基于点的值迭代（PBVI）只关注可达信念点</li><li><strong>在线方法</strong>：实时动态规划（RTDP）、蒙特卡洛树搜索（MCTS）</li><li><strong>简化假设</strong>：使用最可能状态（「最可能信念」方法）或有限历史窗口</li></ul><h2 id="不同模型的比较" tabindex="-1">不同模型的比较</h2><table tabindex="0"><thead><tr><th>环境特征</th><th>适用模型</th></tr></thead><tbody><tr><td>确定性 / 完全可观测</td><td>规划（第 10 章）</td></tr><tr><td>随机 / 完全可观测</td><td>MDP</td></tr><tr><td>随机 / 部分可观测</td><td>POMDP</td></tr></tbody></table>',12)])])}const h=s(r,[["render",l]]);export{_ as __pageData,h as default};
